questionvariables.text:
/*volume of a solid*/
const:rand(5)+3;
denom:rand_with_prohib(-5,20,[0]);
coeff_x:rand(2)+2;
func_y:const+coeff_x*x-x^2;
func_xy:1/denom*x+y=const;

/*solution variables*/
ulim: coeff_x+1/denom;
new_func_xy:const-1/denom*x;
sol1: func_y-(new_func_xy);
sol2:expand(x*(sol1));
sol_int:int(sol2,x);
sol3:int(sol2,x,0,ulim);
sol4:2*pi*(sol3);
ta:decimalplaces(sol4,3);
